import Image from "next/image";
import { db } from "@/lib/db";
import { cn } from "@/lib/utils";
import { PageHeader, Panel } from "@/components/admin/ui";
import { BannerActions, BannerForm } from "@/components/admin/SmallForms";

export default async function AdminBanners() {
  const banners = await db.banner.findMany({ orderBy: [{ sortOrder: "asc" }, { createdAt: "asc" }] });
  return (
    <>
      <PageHeader title="Home page banners" description="The hero carousel at the top of the store." />
      <Panel title="New banner" className="mb-6"><BannerForm /></Panel>
      <div className="space-y-4">
        {banners.map((b) => (
          <div key={b.id} className={cn("flex flex-col gap-4 rounded-lg border border-line bg-white p-3 sm:flex-row", !b.isActive && "opacity-50")}>
            <div className="relative aspect-[8/3] w-full shrink-0 overflow-hidden rounded sm:w-80"><Image src={b.image} alt="" fill sizes="320px" className="object-cover" /></div>
            <div className="flex-1">
              <p className="font-semibold">{b.title}</p>
              {b.subtitle && <p className="text-sm text-muted">{b.subtitle}</p>}
              {b.ctaHref && <p className="mt-1 text-xs">Button: “{b.ctaLabel}” → {b.ctaHref}</p>}
              <div className="mt-2"><BannerActions id={b.id} isActive={b.isActive} /></div>
            </div>
          </div>
        ))}
      </div>
    </>
  );
}
